"""Independent archived-geometry and physical-contract tests; no ROS required."""
import json
from pathlib import Path
import unittest

import numpy as np

from active_arm_model import PiperArmModel, DEFAULT_PARAMETERS, Q_NOMINAL


class ActiveArmModelTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.model = PiperArmModel.from_defaults()

    def test_archived_native_geometry_exact_parity(self):
        # This artifact was recorded by the existing native fixed-arm pipeline,
        # not generated by the module under test.
        record = json.loads((DEFAULT_PARAMETERS.parent/'geometry.json').read_text())
        q = np.deg2rad(record['arm_q_deg'])
        np.testing.assert_allclose(self.model.arm_spheres(q)[:, :3],
                                   record['arm_collision_points_xyz'], rtol=0., atol=2e-15)
        np.testing.assert_allclose(self.model.arm_spheres(q)[:, 3], .034)
        self.assertEqual(self.model.body_spheres(q).shape, (67, 4))

    def test_batch_and_world_rotation_preserve_geometry(self):
        rng = np.random.default_rng(4)
        qs = rng.uniform(self.model.lower, self.model.upper, size=(9, 6))
        poses = rng.uniform(-1., 1., size=(9, 3))
        batch = self.model.body_spheres(qs, poses)
        for q, pose, row in zip(qs, poses, batch):
            local = self.model.body_spheres(q)
            c, s = np.cos(pose[2]), np.sin(pose[2])
            expected = local.copy()
            expected[:, :2] = local[:, :2] @ np.array([[c, s], [-s, c]])+pose[:2]
            np.testing.assert_allclose(row, expected, atol=1e-14)
            np.testing.assert_allclose(row, self.model.body_spheres(q, pose), atol=1e-14)
        frames = self.model.native_transforms(qs)
        np.testing.assert_allclose(frames[:, :, :3, :3] @ frames[:, :, :3, :3].transpose(0, 1, 3, 2),
                                   np.broadcast_to(np.eye(3), (9, 6, 3, 3)), atol=1e-14)

    def test_native_nominal_passes_but_folded_collision_rejected(self):
        nominal = self.model.check(Q_NOMINAL)
        self.assertTrue(nominal['valid'], nominal)
        folded = self.model.check(np.zeros(6))
        self.assertFalse(folded['valid'])
        self.assertIn('arm_self_collision', folded['violations'])
        self.assertLess(folded['min_self_gap'], -.02)

    def test_exclusions_are_explicit_and_do_not_drop_whole_elbow_pair(self):
        policy = self.model.collision_policy()
        self.assertEqual(policy['excluded_base_arm_links'], [0, 1])
        excluded = {(x['sphere_i'], x['sphere_j']): x['reason'] for x in policy['excluded_self_pairs']}
        self.assertEqual(excluded[(3, 14)], 'permanent_joint_sample_overlap')
        self.assertIn([4, 13], policy['checked_self_pairs'])
        self.assertEqual(len(policy['checked_self_pairs'])+len(excluded), 190)
        # The three specifically excluded non-adjacent contacts are structural,
        # not an exclusion inferred from collisions in the chosen experiment.
        rng = np.random.default_rng(12)
        spheres = self.model.arm_spheres(rng.uniform(self.model.lower, self.model.upper, (50, 6)))
        for i, j in [(3, 14), (10, 19), (11, 19)]:
            distances = np.linalg.norm(spheres[:, i, :3]-spheres[:, j, :3], axis=1)
            self.assertLess(float(distances.max()), .068)

    def test_joint_position_velocity_and_acceleration_rejection(self):
        q = Q_NOMINAL.copy(); q[0] = self.model.upper[0]+.001
        self.assertIn('position_limit', self.model.check(q)['violations'])
        self.assertIn('velocity_limit', self.model.check(Q_NOMINAL, np.ones(6))['violations'])
        self.assertIn('acceleration_limit', self.model.check(Q_NOMINAL, np.zeros(6), np.ones(6))['violations'])

    def test_ground_and_base_arm_checks_are_active(self):
        low = PiperArmModel(self.model.fixed_spheres, mount=(.005, 0., -.1, 0., 0., 0.))
        self.assertIn('ground_collision', low.check(Q_NOMINAL)['violations'])
        sphere = self.model.arm_spheres(Q_NOMINAL)[12].copy()
        touching = PiperArmModel(np.vstack([self.model.fixed_spheres, sphere]))
        self.assertIn('base_arm_collision', touching.check(Q_NOMINAL)['violations'])

    def test_joint_step_has_acceleration_velocity_and_position_bounds(self):
        q = Q_NOMINAL.copy(); dq = np.zeros(6)
        step = self.model.integrate(q, dq, np.ones(6)*20., .02)
        self.assertTrue(step['valid'], step)
        np.testing.assert_allclose(step['dq'], np.ones(6)*.018, atol=1e-15)
        np.testing.assert_allclose(step['q'], q+.00018, atol=1e-15)
        np.testing.assert_allclose(step['ddq'], np.ones(6)*.9, atol=1e-14)
        self.assertTrue(step['clipped'])
        # Initial outward motion too near a joint stop cannot be fixed by
        # clamping q; the integration must reject it explicitly.
        q[0] = self.model.upper[0]-1e-5; dq[0] = .4
        result = self.model.integrate(q, dq, np.zeros(6), .02, check_geometry=False)
        self.assertFalse(result['valid'])
        self.assertEqual(result['reason'], 'initial_joint_stop_limit')
        np.testing.assert_array_equal(result['q'], q)

    def test_explicit_batch_api_matches_scalar_checks(self):
        qs = np.random.default_rng(91).uniform(self.model.lower, self.model.upper, (31, 6))
        base = np.random.default_rng(18).normal(size=(31, 3))
        np.testing.assert_allclose(self.model.body_spheres_batch(qs, base), self.model.body_spheres(qs, base))
        expected = [min(check['min_self_gap'], check['min_base_arm_gap'], check['min_ground_gap'])
                    for check in self.model.check_batch(qs)]
        np.testing.assert_allclose(self.model.configuration_gaps_batch(qs), expected, atol=1e-14)
        for method in [self.model.configuration_gaps_batch, self.model.body_spheres_batch]:
            with self.assertRaises(ValueError): method(Q_NOMINAL)

    def test_initial_braking_infeasibility_cannot_hide_in_large_time_step(self):
        q = Q_NOMINAL.copy(); q[0] = self.model.upper[0]-.001
        dq = np.zeros(6); dq[0] = .4
        result = self.model.integrate(q, dq, -dq, 2., check_geometry=False)
        self.assertFalse(result['valid'])
        self.assertEqual(result['reason'], 'initial_joint_stop_limit')

    def test_invalid_inputs_never_become_nominal_safe_state(self):
        for value in [np.full(6, np.nan), np.zeros(5), np.zeros((2, 5))]:
            with self.assertRaises(ValueError): self.model.arm_spheres(value)
        for dt in [0., -1., float('nan')]:
            with self.assertRaises(ValueError): self.model.integrate(Q_NOMINAL, np.zeros(6), np.zeros(6), dt)
        with self.assertRaises(ValueError): self.model.check(Q_NOMINAL, collision_margin=-.01)

    def test_urdf_fk_is_separate_and_rotates_about_urdf_joint_axis(self):
        zero = self.model.urdf_link_transforms(np.zeros(6))
        q = np.zeros(6); q[0] = .3
        rotated = self.model.urdf_link_transforms(q)
        # First joint is z revolute: its translation stays fixed, while its
        # local orientation rotates by exactly the commanded joint angle.
        np.testing.assert_allclose(rotated['link1'][:3, 3], zero['link1'][:3, 3])
        relative = zero['link1'][:3, :3].T @ rotated['link1'][:3, :3]
        c, s = np.cos(.3), np.sin(.3)
        np.testing.assert_allclose(relative, [[c, -s, 0], [s, c, 0], [0, 0, 1]], atol=1e-12)
        self.assertIn('arm_base', zero)


if __name__ == '__main__':
    unittest.main()
